    Momentum: "Momentum",
    "Momentum mandates in the mid, multi and mid-small bands. Almost all launched since {0}, so there is no age floor here: one would empty the screen rather than improve it.":
      "মিড, মাল্টি ও মিড-স্মল ব্যান্ডে মোমেন্টাম ম্যান্ডেট। প্রায় সবই {0}-এর পর চালু হয়েছে, তাই এখানে বয়সের কোনো ন্যূনতম সীমা নেই: সেটা স্ক্রিনকে ভালো করার বদলে খালি করে দিত।",
    "Momentum mandates in the mid, multi and mid-small bands. Almost all of these are index funds launched since {0}, so there is no age floor here: one would empty the screen rather than raise its quality. Judge them on the short record they have and on tracking behaviour, not on five-year columns that are blank.":
      "মিড, মাল্টি ও মিড-স্মল ব্যান্ডে মোমেন্টাম ম্যান্ডেট। এগুলোর প্রায় সবই {0}-এর পর চালু হওয়া ইনডেক্স ফান্ড, তাই এখানে বয়সের কোনো ন্যূনতম সীমা নেই: সেটা স্ক্রিনের মান বাড়ানোর বদলে খালি করে দিত। এদের যতটুকু ছোট রেকর্ড আছে তা ও ট্র্যাকিংয়ের আচরণ দিয়ে বিচার করুন, ফাঁকা পাঁচ বছরের কলাম দিয়ে নয়।",
    "Momentum {0}-{1}": "মোমেন্টাম {0}-{1}",
    "Money cannot be withdrawn for": "টাকা তোলা যাবে না",
    "Money in this exact plan (quarterly average)": "ঠিক এই প্ল্যানে টাকা (ত্রৈমাসিক গড়)",
    "Monthly data smooths intra-month drawdowns.":
      "মাসিক ডেটা মাসের মাঝের ড্রডাউনকে মসৃণ করে দেয়।",
    "Most of these are younger than three years. There is no long record to judge them on, and this screen does not pretend otherwise.":
      "এগুলোর বেশিরভাগই তিন বছরের কম পুরোনো। বিচার করার মতো লম্বা রেকর্ড নেই, আর এই স্ক্রিন তার উল্টো ভান করে না।",
    "Multi Cap": "Multi Cap",
    NAV: "NAV",
    "NAV history is stored for this scheme but the metrics snapshot was built before it arrived. Run `make metrics` to include it.":
      "এই স্কিমের NAV ইতিহাস রাখা আছে, কিন্তু মেট্রিক স্ন্যাপশট তা আসার আগে তৈরি হয়েছিল। এটি যোগ করতে `make metrics` চালান।",
    "NAV_T is the latest month-end NAV; NAV_{T-h} is the observation h years earlier, accepted only within {0} days of that month end.":
      "NAV_T হলো সর্বশেষ মাস-শেষের NAV; NAV_{T-h} হলো h বছর আগের পর্যবেক্ষণ, শুধু সেই মাস-শেষের {0} দিনের মধ্যে হলে গ্রহণ করা হয়।",
    "NIFTY_BANK_PROXY is an index-fund proxy, not the index: it is net of that fund's expenses and tracking error, so it understates the benchmark and flatters every fund measured against it.":
      "NIFTY_BANK_PROXY একটি ইনডেক্স-ফান্ড প্রক্সি, ইনডেক্স নয়: এটি সেই ফান্ডের খরচ ও ট্র্যাকিং এরর বাদ দিয়ে, তাই বেঞ্চমার্ককে কম করে দেখায় এবং এর বিপরীতে মাপা প্রতিটি ফান্ডকে ভালো দেখায়।",
